    /// Thread ID (`thr_...`) this schedule is bound to. When set, the scheduled task is delivered into the thread rather than creating a new session. `null` for session-based schedules.
    public var thread: String?
    /// IANA timezone name used to interpret the cron expression or `scheduled_at` (e.g. `"America/New_York"`). Defaults to `"Etc/UTC"`.
    public var timezone: String?
    /// When the schedule was last modified (ISO 8601).
    public var updatedAt: Date?

    public init(
        agent: String? = nil,
        app: String? = nil,
        createdAt: Date? = nil,
        cronExpression: String? = nil,
        id: String,
        instructions: String? = nil,
        lastRunAt: Date? = nil,
        maxRuns: Int? = nil,
        metadata: [String: JSONValue]? = nil,
        nextRunAt: Date? = nil,
        runCount: Int? = nil,
        scheduleType: String? = nil,
        scheduledAt: Date? = nil,
        status: String? = nil,
        thread: String? = nil,
        timezone: String? = nil,
        updatedAt: Date? = nil
    ) {
        self.agent = agent
        self.app = app
        self.createdAt = createdAt
        self.cronExpression = cronExpression
        self.id = id
        self.instructions = instructions
        self.lastRunAt = lastRunAt
        self.maxRuns = maxRuns
        self.metadata = metadata
        self.nextRunAt = nextRunAt
        self.runCount = runCount
        self.scheduleType = scheduleType
        self.scheduledAt = scheduledAt
        self.status = status
        self.thread = thread
        self.timezone = timezone
        self.updatedAt = updatedAt
    }

    private enum CodingKeys: String, CodingKey {
        case agent
        case app
        case createdAt = "created_at"
        case cronExpression = "cron_expression"
        case id
        case instructions
        case lastRunAt = "last_run_at"
        case maxRuns = "max_runs"
        case metadata
        case nextRunAt = "next_run_at"
        case runCount = "run_count"
        case scheduleType = "schedule_type"
        case scheduledAt = "scheduled_at"
        case status
        case thread
        case timezone
        case updatedAt = "updated_at"
    }
}

